func precipColor(prob int) string {
	switch {
	case prob > 70:
		return "#3b82f6"
	case prob > 30:
		return "#60a5fa"
	default:
		return "#93c5fd"
	}
}

func weatherIcon(condition string) string {
	switch condition {
	case "sunny":
		return "☀️"
	case "partlycloudy":
		return "⛅"
	case "cloudy":
		return "☁️"
	case "rainy":
		return "🌧"
	case "pouring":
		return "🌧"
	case "snowy":
		return "🌨"
	case "fog":
		return "🌫"
	case "lightning":
		return "⛈"
	case "clear-night":
		return "🌙"
	case "windy":
		return "💨"
	default:
		return "☀️"
	}
}

