func alertClass(s string) string {
	switch s {
	case "critical":
		return "alert-error"
	case "severe":
		return "alert-warning"
	case "warning":
		return "alert-warning"
	default:
		return "alert-info"
	}
}

func severityIcon(s string) string {
	switch s {
	case "critical":
		return "🔴"
	case "severe":
		return "🟠"
	case "warning":
		return "🟡"
	default:
		return "🔵"
	}
}

